import Phaser from 'phaser';
import { createResult, RESULT_EVENT, validateActivity } from './contracts.js';

export class BaseGameScene extends Phaser.Scene {
  init(activity) {
    this.activity = validateActivity(activity);
    this.metrics = { attempts: 0, correct: 0, hints: 0 };
    this.finished = false;
    this.failedImages = [];
  }
  preload() {
    this.load.on('loaderror', file => this.failedImages.push(file.key));
    for (const image of this.activity.images) this.load.image(image.id, image.url);
  }
  create() {
    if (this.failedImages.length) {
      this.game.events.emit('activity-error', 'Não foi possível carregar as imagens. Volte ao menu e tente novamente.');
      return;
    }
    this.buildBoard();
  }
  buildBoard() {
    this.add.text(480, 90, 'Atividade em preparação', { fontSize: '30px', color: '#183b39' }).setOrigin(0.5);
    this.add.text(480, 145, 'As imagens já estão prontas para o jogo.', { fontSize: '22px', color: '#183b39' }).setOrigin(0.5);
    this.activity.images.forEach((image, i) => this.add.image(480 + (i - (this.activity.images.length - 1) / 2) * 220, 330, image.id).setDisplaySize(180, 180));
  }
  finish(status) {
    if (this.finished) return;
    this.finished = true;
    this.game.events.emit(RESULT_EVENT, createResult(this.activity, { status, ...this.metrics }));
  }
}
export const GAME_IDS = Object.freeze(['memory', 'puzzle', 'sequence']);
export const RESULT_EVENT = 'activity-result';
const requiredImages = { memory: 3, puzzle: 1, sequence: 2 };

export function validateActivity(activity) {
  if (!activity || typeof activity.activityId !== 'string' || !activity.activityId.trim()) throw new Error('Atividade sem identificador.');
  if (!GAME_IDS.includes(activity.gameId)) throw new Error('Jogo desconhecido.');
  if (typeof activity.theme !== 'string' || !activity.theme.trim()) throw new Error('Tema ausente.');
  if (!Array.isArray(activity.images) || activity.images.length !== requiredImages[activity.gameId]) throw new Error('Quantidade de imagens inválida.');
  const ids = new Set();
  for (const image of activity.images) {
    if (!image || typeof image.id !== 'string' || !image.id || typeof image.url !== 'string' || !image.url || typeof image.description !== 'string' || !image.description.trim() || ids.has(image.id)) throw new Error('Imagem inválida ou identificador duplicado.');
    const url = new URL(image.url, 'https://local.invalid');
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error('Protocolo de imagem não permitido.');
    ids.add(image.id);
  }
  return activity;
}

// Metrics count user actions: pair comparisons, piece placements, or answer selections.
export function createResult(activity, { status, attempts = 0, correct = 0, hints = 0 }) {
  validateActivity(activity);
  if (!['completed', 'abandoned'].includes(status)) throw new Error('Estado inválido.');
  if (![attempts, correct, hints].every(n => Number.isSafeInteger(n) && n >= 0) || correct > attempts) throw new Error('Contadores inválidos.');
  return { activityId: activity.activityId, gameId: activity.gameId, status, attempts, correct, hints };
}
export function demoActivity(gameId) {
  const count = { memory: 3, puzzle: 1, sequence: 2 }[gameId];
  return { activityId: crypto.randomUUID(), gameId, theme: 'dinossauros', images: Array.from({ length: count ?? 0 }, (_, i) => ({ id: `dino-${i + 1}`, url: `/assets/demo/dino-${i + 1}.svg`, description: ['Dinossauro verde', 'Dinossauro azul', 'Dinossauro laranja'][i] })), settings: { sound: false, reducedMotion: matchMedia('(prefers-reduced-motion: reduce)').matches } };
}
