import { BaseGameScene } from '../../core/BaseGameScene.js';

const INK = '#183b39';
const SLOT = 130;
const OPTION = 170;

function fit(image, width, height) {
  const scale = Math.min(width / image.width, height / image.height);
  return image.setDisplaySize(image.width * scale, image.height * scale);
}

function shuffled(items) {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

// Padrão A-B-A-B-? com duas alternativas; A (images[0]) é a resposta correta.
export class SequenceScene extends BaseGameScene {
  buildBoard() {
    const [a, b] = this.activity.images;
    this.solved = false;
    this.options = [];

    this.add.text(480, 50, 'Qual vem depois?', { fontSize: '34px', color: INK, fontStyle: 'bold' }).setOrigin(0.5);

    const pattern = [a, b, a, b];
    const startX = 480 - 2 * (SLOT + 30);
    const slotY = 190;
    pattern.forEach((image, i) => this.drawSlot(startX + i * (SLOT + 30), slotY, image));
    this.gapX = startX + 4 * (SLOT + 30);
    this.gapY = slotY;
    this.drawGap();

    this.feedback = this.add.text(480, 330, 'Toque na imagem que completa a sequência.', { fontSize: '24px', color: INK }).setOrigin(0.5);

    const order = shuffled([a, b]);
    order.forEach((image, i) => this.drawOption(image, 330 + i * 300, 460));
  }

  drawSlot(x, y, image) {
    this.add.rectangle(x, y, SLOT, SLOT, 0xffffff).setStrokeStyle(3, 0x54876b);
    fit(this.add.image(x, y, image.id), SLOT - 16, SLOT - 16);
  }

  drawGap() {
    this.gap = this.add.rectangle(this.gapX, this.gapY, SLOT, SLOT, 0xffffff).setStrokeStyle(3, 0x183b39);
    this.gapMark = this.add.text(this.gapX, this.gapY, '?', { fontSize: '64px', color: INK, fontStyle: 'bold' }).setOrigin(0.5);
  }

  drawOption(image, x, y) {
    const card = this.add.rectangle(x, y, OPTION, OPTION, 0xffffff).setStrokeStyle(3, 0x54876b);
    const picture = fit(this.add.image(x, y, image.id), OPTION - 20, OPTION - 20);
    const label = this.add.text(x, y + OPTION / 2 + 18, image.description, { fontSize: '18px', color: INK }).setOrigin(0.5);
    card.setInteractive({ useHandCursor: true });
    card.on('pointerover', () => { if (!this.solved) card.setStrokeStyle(5, 0x183b39); });
    card.on('pointerout', () => card.setStrokeStyle(3, 0x54876b));
    card.on('pointerup', () => this.choose(image, card, picture));
    this.options.push({ card, picture, label });
  }

  choose(image, card, picture) {
    if (this.solved || this.finished) return;
    this.metrics.attempts += 1;
    if (image.id === this.activity.images[0].id) {
      this.solved = true;
      this.metrics.correct += 1;
      this.options.forEach(option => option.card.disableInteractive());
      this.gapMark.destroy();
      fit(this.add.image(this.gapX, this.gapY, image.id), SLOT - 16, SLOT - 16);
      this.gap.setStrokeStyle(4, 0x2f7d4f);
      this.feedback.setText('Muito bem! Você completou a sequência.');
      this.finish('completed');
      return;
    }
    this.feedback.setText('Quase! Olhe de novo o padrão e tente outra vez.');
    if (!this.activity.settings?.reducedMotion) {
      this.tweens.killTweensOf(picture);
      const baseX = card.x;
      picture.x = baseX;
      this.tweens.add({ targets: picture, x: baseX + 8, duration: 70, yoyo: true, repeat: 2, onComplete: () => { picture.x = baseX; } });
    }
  }
}

