async (page) => {
  const log = [];
  await page.evaluate(() => { window.__r = []; if (!window.__h) { window.__h = 1; window.addEventListener('activity-result', e => window.__r.push(e.detail)); } });
  const at = async (x, y) => { const b = await page.locator('#game canvas').boundingBox(); return [b.x + x * b.width / 960, b.y + y * b.height / 600]; };
  const click = async (x, y) => { const [px, py] = await at(x, y); await page.mouse.click(px, py); await page.waitForTimeout(150); };
  // rodadas: entra, clica esquerda; se concluiu, sai e reentra até a esquerda ser a errada
  for (let round = 0; round < 8; round++) {
    await page.evaluate(() => { window.__r = []; });
    await click(330, 460);
    let r = await page.evaluate(() => window.__r.slice());
    if (r.length === 0) {
      log.push({ round, leftWrong: true });
      await click(330, 460); // erro repetido
      await page.screenshot({ path: '.playwright-mcp/seq-erro.png' });
      const [px, py] = await at(630, 460);
      await page.mouse.dblclick(px, py); // duplo clique na correta
      await page.waitForTimeout(200);
      await click(630, 460); await click(330, 460); // cliques após concluir
      await page.screenshot({ path: '.playwright-mcp/seq-fim.png' });
      log.push({ results: await page.evaluate(() => window.__r.slice()) });
      await page.locator('#exit').click();
      log.push({ afterExit: await page.evaluate(() => window.__r.slice()) });
      return log;
    }
    log.push({ round, leftCorrect: r });
    await page.locator('#exit').click();
    await page.locator('[data-game="sequence"]').click();
    await page.waitForTimeout(500);
  }
  return log;
}

