async (page) => {
  const out = {};
  const ctx = page.context();
  // 1) Toque: nova página com touch habilitado
  const browser = ctx.browser();
  const tctx = await browser.newContext({ hasTouch: true, isMobile: true, viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  const tp = await tctx.newPage();
  await tp.goto('http://127.0.0.1:5177/');
  await tp.evaluate(() => { window.__r = []; window.addEventListener('activity-result', e => window.__r.push(e.detail)); });
  const tapAt = async (p, x, y) => { const b = await p.locator('#game canvas').boundingBox(); await p.touchscreen.tap(b.x + x * b.width / 960, b.y + y * b.height / 600); await p.waitForTimeout(150); };
  await tp.locator('[data-game="sequence"]').tap();
  await tp.waitForTimeout(600);
  await tapAt(tp, 330, 460); await tapAt(tp, 630, 460);
  await tp.screenshot({ path: '.playwright-mcp/seq-touch.png' });
  out.touch = await tp.evaluate(() => window.__r);
  await tctx.close();

  // 2) Reentrada: ordem embaralhada e estado reiniciado; saída sem concluir gera abandoned com contadores da partida
  await page.evaluate(() => { window.__r = []; });
  const firstCorrect = [];
  for (let i = 0; i < 6; i++) {
    await page.locator('[data-game="sequence"]').click();
    await page.waitForTimeout(400);
    const b = await page.locator('#game canvas').boundingBox();
    await page.mouse.click(b.x + 330 * b.width / 960, b.y + 460 * b.height / 600);
    await page.waitForTimeout(150);
    const r = await page.evaluate(() => window.__r.splice(0));
    await page.locator('#exit').click();
    const after = await page.evaluate(() => window.__r.splice(0));
    firstCorrect.push({ during: r.map(x => x.status + ':' + x.attempts + '/' + x.correct), onExit: after.map(x => x.status + ':' + x.attempts + '/' + x.correct) });
  }
  out.reentry = firstCorrect;
  return out;
}

